<?php require_once 'includes/config.php'; if(user()) redirect('index.php'); $title='Register'; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(strlen($pass)<8){flash('danger','Password must be at least 8 characters.');}else{try{$st=db()->prepare('INSERT INTO users(name,email,password,role,status) VALUES(?,?,? ,"customer",1)');$st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('success','Account created. Please login.');redirect('login.php');}catch(PDOException $e){flash('danger','That email is already registered.');}}}require 'includes/header.php'; ?><div class="row justify-content-center"><div class="col-md-6"><div class="bg-white border rounded-4 p-4"><h2>Create Customer Account</h2><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input name="name" class="form-control mb-3" placeholder="Full name" required><input name="email" type="email" class="form-control mb-3" placeholder="Email" required><input name="password" type="password" class="form-control mb-3" placeholder="Password (8+ characters)" required><button class="btn btn-purple w-100">Create Account</button></form></div></div></div><?php require 'includes/footer.php'; ?>
